'use client';
import { motion } from 'motion/react';

export function FadeIn({ children }: { children: React.ReactNode }) {
  return (
    <motion.div initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: 'easeOut' }}>
      {children}
    </motion.div>
  );
}

import { autoAnimateRef } from '@formkit/auto-animate/react';

export function List({ items }: { items: string[] }) {
  const ref = autoAnimateRef<HTMLUListElement>();
  return (
    <ul ref={ref}>
      {items.map((i) => <li key={i}>{i}</li>)}
    </ul>
  );
}

import * as THREE from 'three';

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, innerWidth / innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);
scene.add(new THREE.Mesh(new THREE.BoxGeometry(), new THREE.MeshNormalMaterial()));
camera.position.z = 3;
renderer.setAnimationLoop(() => renderer.render(scene, camera));

import { createClient } from '@supabase/supabase-js';

export const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

export async function getArticles() {
  const res = await fetch('http://localhost:1337/api/articles?populate=cover', {
    headers: { Authorization: `Bearer ${process.env.STRAPI_API_TOKEN}` },
    next: { revalidate: 60 },
  });
  return res.json();
}

